// Related cards: prefer same category, but spread usage so no cover repeats across many pages.
const relUse = new Map();
const relatedOf = p => {
  const pick = posts.filter(x => x !== p)
    .map((x, i) => ({ x, i, s: (relUse.get(x) || 0) * 2 + (x.cat === p.cat ? 0 : 1) }))
    .sort((a, b) => a.s - b.s || a.i - b.i).slice(0, 3).map(o => o.x);
  pick.forEach(x => relUse.set(x, (relUse.get(x) || 0) + 1));
  return pick;
};

